import 'package:drift/drift.dart';
import '../../../core/database/app_database.dart';
import '../../../core/database/helpers/text_normalizer.dart';
import '../../../core/database/helpers/uuid_generator.dart';
import '../../../core/database/tables.dart';

class MessageNumberRepository {
  MessageNumberRepository({required AppDatabase db, required String companyId, required String actorId, required String actorName}) : _db = db, _companyId = companyId, _actorId = actorId, _actorName = actorName;
  final AppDatabase _db; final String _companyId; final String _actorId; final String _actorName;
  Stream<List<CompanyMessageNumberRow>> watchAll() => _db.messageNumbersDao.watchAll(companyId: _companyId); Stream<List<CompanyMessageNumberRow>> watchActive() => _db.messageNumbersDao.watchActive(companyId: _companyId); Future<List<CompanyMessageNumberRow>> getAll() => _db.messageNumbersDao.getAll(companyId: _companyId); Future<CompanyMessageNumberRow?> getById(String id) => _db.messageNumbersDao.getById(id);
  Future<String> add({required String channel, required String phoneE164, String? label, bool isDefault = false}) async { if (!{'sms', 'whatsapp'}.contains(channel)) throw ArgumentError('القناة غير مدعومة: $channel'); final phone = TextNormalizer.normalizePhone(phoneE164); if (phone.isEmpty) throw ArgumentError('رقم الرسائل غير صالح'); return _db.transaction(() async { if (await _db.messageNumbersDao.existsByChannelAndPhone(companyId: _companyId, channel: channel, phoneE164: phone)) throw StateError('الرقم موجود مسبقاً على قناة $channel'); if (isDefault) await _db.messageNumbersDao.unsetChannelDefaults(companyId: _companyId, channel: channel); final now = DateTime.now().toUtc(), id = UuidGenerator.random(); await _db.into(_db.companyMessageNumbersTable).insert(CompanyMessageNumbersTableCompanion.insert(id: id, companyId: _companyId, channel: channel, phoneE164: phone, label: Value(label), isDefault: Value(isDefault), status: const Value('active'), createdAt: now, updatedAt: now)); await _enqueue(id, 'create', {'id': id, 'channel': channel, 'phoneE164': phone, 'label': label, 'isDefault': isDefault}, now); return id; }); }
  Future<void> update({required String id, String? label, bool? isDefault, String? status}) async { await _db.transaction(() async { final old = await getById(id); if (old == null) throw StateError('رقم الرسائل غير موجود: $id'); if (isDefault == true && !old.isDefault) await _db.messageNumbersDao.unsetChannelDefaults(companyId: _companyId, channel: old.channel); final now = DateTime.now().toUtc(); await (_db.update(_db.companyMessageNumbersTable)..where((t) => t.id.equals(id))).write(CompanyMessageNumbersTableCompanion(label: label == null ? const Value.absent() : Value(label), isDefault: isDefault == null ? const Value.absent() : Value(isDefault), status: status == null ? const Value.absent() : Value(status), updatedAt: Value(now))); await _enqueue(id, 'update', {'id': id, if (label != null) 'label': label, if (isDefault != null) 'isDefault': isDefault, if (status != null) 'status': status}, now); }); }
  Future<void> delete(String id) async { await _db.transaction(() async { if (await getById(id) == null) return; final now = DateTime.now().toUtc(); await _db.messageNumbersDao.deleteNumber(id); await _enqueue(id, 'delete', {'id': id}, now); }); }
  Future<void> _enqueue(String id, String operation, Map<String, dynamic> payload, DateTime now) => _db.outboxDao.enqueue(OutboxTableCompanion.insert(operationId: UuidGenerator.random(), companyId: _companyId, entityType: 'company_message_numbers', entityId: id, entityKey: '$_companyId|company_message_numbers|$id', operation: operation, payload: payload, createdAt: now, updatedAt: now));
}
